import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: RefreshPostsPage(), debugShowCheckedModeBanner: false));
class RefreshPostsPage extends StatefulWidget { const RefreshPostsPage({super.key}); @override State<RefreshPostsPage> createState() => _RefreshPostsPageState(); }
class _RefreshPostsPageState extends State<RefreshPostsPage> { List<dynamic> posts = []; bool loading = true; String? error; @override void initState() { super.initState(); load(); } Future<void> load() async { try { final r = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts')); if (r.statusCode != 200) throw Exception('HTTP ${r.statusCode}'); final data = jsonDecode(r.body) as List<dynamic>; if (mounted) setState(() { posts = data; error = null; }); } catch (e) { if (mounted) setState(() => error = '$e'); } finally { if (mounted) setState(() => loading = false); } }
 @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q13: Pull to refresh')), body: loading ? const Center(child: CircularProgressIndicator()) : error != null ? Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Text('Error: $error'), ElevatedButton(onPressed: () { setState(() => loading = true); load(); }, child: const Text('Retry'))])) : RefreshIndicator(onRefresh: load, child: ListView.builder(physics: const AlwaysScrollableScrollPhysics(), itemCount: posts.length, itemBuilder: (context, i) => ListTile(leading: CircleAvatar(child: Text('${posts[i]['id']}')), title: Text('${posts[i]['title']}'), subtitle: Text('${posts[i]['body']}', maxLines: 2, overflow: TextOverflow.ellipsis)))));
}
